  /* ============ 第二層深化：每個事件多一格「內心獨白」，每個選項多一格「後來發生了什麼」 ============ */
  function X(id, inner, aft) {
    const ev = CSTORY.all().find(x => x.id === id); if (!ev || !Array.isArray(ev.beats)) return;
    if (inner) {
      const b = beat(inner), used = ev.beats.map(x => x.scene + '|' + x.shot), alt = ['close+vig', 'L', 'R', 'low', 'top+dim', 'far', 'close+cold', 'wide+vig'];
      for (let i = 0; used.indexOf(b.scene + '|' + b.shot) >= 0 && i < alt.length; i++) b.shot = alt[i];      // 同一事件的每一格鏡頭都不同
      ev.beats.splice(Math.max(0, ev.beats.length - 1), 0, b);      // 插在最後一格（抉擇）之前
    }
    Object.keys(aft || {}).forEach(cid => { const c = ev.choices.find(x => x.id === cid); if (c && Array.isArray(c.after)) c.after.push(beat(aft[cid])); });
  }
